const rows = $input.all().map((item) => item.json || {});
const values = {};
const presentKeys = new Set();

for (const row of rows) {
  if (typeof row.name === 'string') {
    presentKeys.add(row.name);
    values[row.name] = row.data;
  }
}

const requiredKeys = [
  'NEXCLOUD_BASE_URL',
  'NEXCLOUD_CALENDAR_USER',
  'NEXCLOUD_CALENDAR_PASSWORD',
  'TIMEZONE',
  'REDIS_HOST',
  'REDIS_PORT',
  'REDIS_PASSWORD',
  'REDIS_DATABASE',
];

const missing = requiredKeys.filter((key) => !presentKeys.has(key));
if (missing.length) {
  throw new Error(`Missing required public.key_value_store keys: ${missing.join(', ')}`);
}

const baseUrl = String(values.NEXCLOUD_BASE_URL ?? '').trim().replace(/\/+$/, '');
const user = String(values.NEXCLOUD_CALENDAR_USER ?? '').trim();
const password = String(values.NEXCLOUD_CALENDAR_PASSWORD ?? '');
const timezone = String(values.TIMEZONE ?? '').trim();
const redisHost = String(values.REDIS_HOST ?? '').trim();
const redisPort = Number(values.REDIS_PORT);
const redisDatabase = Number(values.REDIS_DATABASE);

if (!baseUrl || !user || !timezone || !redisHost) {
  throw new Error('NEXCLOUD_BASE_URL, NEXCLOUD_CALENDAR_USER, TIMEZONE, and REDIS_HOST must not be empty');
}
if (!Number.isInteger(redisPort) || redisPort <= 0 || redisPort > 65535) {
  throw new Error(`Invalid REDIS_PORT: ${values.REDIS_PORT}`);
}
if (!Number.isInteger(redisDatabase) || redisDatabase < 0) {
  throw new Error(`Invalid REDIS_DATABASE: ${values.REDIS_DATABASE}`);
}

return [{
  json: {
    nextcloud: {
      baseUrl,
      user,
      password,
    },
    timezone,
    redisExpected: {
      host: redisHost,
      port: redisPort,
      database: redisDatabase,
      passwordConfigured: String(values.REDIS_PASSWORD ?? '').length > 0,
    },
    cache: {
      key: 'calendar-notifier:calendar-sources:v1',
      persistent: true,
      schemaVersion: 1,
    },
  },
}];

const cfg = $input.first().json;
const configuredBaseUrl = String(cfg.nextcloud.baseUrl || '').trim();
const user = cfg.nextcloud.user;
const password = cfg.nextcloud.password;

// Normalize and resolve URLs without relying on the WHATWG `URL` global.
// n8n 2.7.x task-runner sandboxes may not expose `URL` inside Code nodes.
const parseAbsoluteHttpUrl = (value) => {
  const text = String(value || '').trim();
  const match = text.match(/^(https?):\/\/([^\/?#]+)(\/[^?#]*)?(?:\?[^#]*)?(?:#.*)?$/i);
  if (!match) return null;
  return {
    scheme: match[1].toLowerCase(),
    authority: match[2],
    origin: `${match[1].toLowerCase()}://${match[2]}`,
    path: match[3] || '/',
  };
};

const normalizePath = (value) => {
  const parts = [];
  for (const part of String(value || '/').split('/')) {
    if (!part || part === '.') continue;
    if (part === '..') {
      parts.pop();
      continue;
    }
    parts.push(part);
  }
  return `/${parts.join('/')}`;
};

const ensureTrailingSlash = (value) => value.endsWith('/') ? value : `${value}/`;

const resolveUrl = (href, base) => {
  const raw = String(href || '').trim();
  if (!raw) return null;
  if (/^https?:\/\//i.test(raw)) return raw;

  const parsedBase = parseAbsoluteHttpUrl(base);
  if (!parsedBase) return raw;
  if (raw.startsWith('//')) return `${parsedBase.scheme}:${raw}`;

  if (raw.startsWith('/')) {
    return `${parsedBase.origin}${normalizePath(raw)}${raw.endsWith('/') ? '/' : ''}`.replace(/([^:]\/)\/+/g, '$1');
  }

  const basePath = parsedBase.path.endsWith('/')
    ? parsedBase.path
    : parsedBase.path.replace(/\/[^/]*$/, '/');
  const resolvedPath = normalizePath(`${basePath}/${raw}`);
  return `${parsedBase.origin}${resolvedPath}${raw.endsWith('/') ? '/' : ''}`.replace(/([^:]\/)\/+/g, '$1');
};

const parsedConfiguredBase = parseAbsoluteHttpUrl(configuredBaseUrl);
if (!parsedConfiguredBase) {
  throw new Error(`NEXCLOUD_BASE_URL is not a valid absolute HTTP(S) URL: ${configuredBaseUrl}`);
}

let instancePath = parsedConfiguredBase.path.replace(/\/+$/, '');
const davMarker = '/remote.php/dav';
const davIndex = instancePath.indexOf(davMarker);
if (davIndex >= 0) instancePath = instancePath.slice(0, davIndex);
if (instancePath === '/') instancePath = '';

const instanceBaseUrl = `${parsedConfiguredBase.origin}${instancePath}`;
const davRootUrl = `${instanceBaseUrl}${davMarker}/`;

const decodeXml = (value = '') => String(value)
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&apos;/gi, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
  .replace(/&amp;/gi, '&');

const textContent = (fragment = '') => decodeXml(
  String(fragment)
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]+>/g, '')
    .trim(),
);

const firstTag = (block, tag) => {
  const re = new RegExp(`<(?:\\w+:)?${tag}\\b[^>]*>([\\s\\S]*?)<\\/(?:\\w+:)?${tag}>`, 'i');
  return String(block || '').match(re)?.[1] ?? null;
};

const firstHref = (block) => {
  const inner = firstTag(block, 'href');
  return inner === null ? null : textContent(inner);
};

const absoluteUrl = (href, base = davRootUrl) => resolveUrl(href, base);

const bodyToText = (body) => {
  if (body === undefined || body === null) return '';
  if (typeof body === 'string') return body;
  if (Buffer.isBuffer(body)) return body.toString('utf8');
  if (typeof body === 'object') {
    try { return JSON.stringify(body); } catch { return String(body); }
  }
  return String(body);
};

const compactPreview = (value, max = 1400) => String(value || '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);

const statusHint = (status, responseBody, requestUrl) => {
  const lower = String(responseBody || '').toLowerCase();

  if (status === 400 && (lower.includes('trusted domain') || lower.includes('untrusted domain'))) {
    const host = parseAbsoluteHttpUrl(requestUrl)?.authority || requestUrl;
    return `Nextcloud rejected the Docker-network hostname as an untrusted domain. Add "${host}" to Nextcloud trusted_domains (or use an internal URL whose host is already trusted).`;
  }
  if (status === 400) {
    return 'Nextcloud returned HTTP 400. The response preview below should contain the server reason. Common causes are an untrusted Docker hostname, a malformed NEXCLOUD_BASE_URL, or a reverse proxy rejecting WebDAV requests.';
  }
  if (status === 401 || status === 403) {
    return 'Authentication was rejected. Verify NEXCLOUD_CALENDAR_USER/PASSWORD. If the account uses 2FA or external authentication, use a Nextcloud app password for DAV access.';
  }
  if (status === 404) {
    return 'The DAV endpoint was not found. NEXCLOUD_BASE_URL should point to the Nextcloud instance root (or directly to /remote.php/dav), including any installation subpath.';
  }
  if (status === 405 || status === 501) {
    return 'PROPFIND is being rejected by the HTTP server or reverse proxy. Ensure WebDAV methods are allowed between n8n and the internal Nextcloud service.';
  }
  return 'Check the response preview and Nextcloud/reverse-proxy logs for the matching request.';
};

const propfind = async (label, url, depth, body) => {
  const response = await this.helpers.httpRequest({
    method: 'PROPFIND',
    url,
    auth: {
      username: user,
      password,
    },
    headers: {
      Depth: String(depth),
      Accept: 'application/xml, text/xml;q=0.9, */*;q=0.1',
      'Content-Type': 'application/xml; charset=UTF-8',
    },
    body,
    encoding: 'text',
    timeout: 30000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });

  const status = Number(response?.statusCode ?? 0);
  const xml = bodyToText(response?.body);

  if (status < 200 || status >= 300) {
    const hint = statusHint(status, xml, url);
    const preview = compactPreview(xml) || '(empty response body)';
    throw new Error(`${label} failed with HTTP ${status || 'unknown'} at ${url}. ${hint} Response: ${preview}`);
  }

  if (!/<(?:\w+:)?multistatus\b/i.test(xml)) {
    const preview = compactPreview(xml) || '(empty response body)';
    throw new Error(`${label} returned HTTP ${status} but not a DAV multistatus document at ${url}. Response: ${preview}`);
  }

  return { status, xml };
};

// Step 1: ask DAV who the authenticated principal actually is. This avoids
// assuming that NEXCLOUD_CALENDAR_USER is identical to the internal Nextcloud UID.
const principalRequestBody = `<?xml version="1.0" encoding="UTF-8"?>
<d:propfind xmlns:d="DAV:">
  <d:prop>
    <d:current-user-principal />
  </d:prop>
</d:propfind>`;

const principalDiscovery = await propfind(
  'Nextcloud DAV principal discovery',
  davRootUrl,
  0,
  principalRequestBody,
);

const principalBlock = firstTag(principalDiscovery.xml, 'current-user-principal');
let principalHref = principalBlock === null ? null : firstHref(principalBlock);
let principalUrl = absoluteUrl(principalHref);
let principalDiscoveryMode = 'dav_current_user_principal';

if (!principalUrl) {
  principalUrl = resolveUrl(`principals/users/${encodeURIComponent(user)}/`, davRootUrl);
  principalDiscoveryMode = 'username_fallback';
}

// Step 2: ask the principal for its calendar home. This is more robust than
// directly constructing /calendars/<login>/ for installations with non-trivial UIDs.
const calendarHomeRequestBody = `<?xml version="1.0" encoding="UTF-8"?>
<d:propfind xmlns:d="DAV:" xmlns:c="urn:ietf:params:xml:ns:caldav">
  <d:prop>
    <c:calendar-home-set />
  </d:prop>
</d:propfind>`;

const calendarHomeDiscovery = await propfind(
  'Nextcloud CalDAV calendar-home discovery',
  principalUrl,
  0,
  calendarHomeRequestBody,
);

const homeBlock = firstTag(calendarHomeDiscovery.xml, 'calendar-home-set');
let calendarHomeHref = homeBlock === null ? null : firstHref(homeBlock);
let calendarHomeUrl = absoluteUrl(calendarHomeHref, principalUrl);
let calendarHomeDiscoveryMode = 'caldav_calendar_home_set';

if (!calendarHomeUrl) {
  calendarHomeUrl = resolveUrl(`calendars/${encodeURIComponent(user)}/`, davRootUrl);
  calendarHomeDiscoveryMode = 'username_fallback';
}

if (!calendarHomeUrl.endsWith('/')) calendarHomeUrl += '/';

// Step 3: list every calendar/subscription in the calendar home.
const calendarsRequestBody = `<?xml version="1.0" encoding="UTF-8"?>
<d:propfind xmlns:d="DAV:"
            xmlns:c="urn:ietf:params:xml:ns:caldav"
            xmlns:cs="http://calendarserver.org/ns/"
            xmlns:oc="http://owncloud.org/ns">
  <d:prop>
    <d:displayname />
    <d:resourcetype />
    <cs:source />
    <c:supported-calendar-component-set />
    <oc:read-only />
  </d:prop>
</d:propfind>`;

const calendarDiscovery = await propfind(
  'Nextcloud calendar listing',
  calendarHomeUrl,
  1,
  calendarsRequestBody,
);

const normalizeSubscriptionUrl = (value) => {
  if (!value) return null;
  let url = value.trim();
  if (/^webcal:\/\//i.test(url)) url = url.replace(/^webcal:/i, 'http:');
  if (/^webcals:\/\//i.test(url)) url = url.replace(/^webcals:/i, 'https:');
  return url;
};

const responseBlocks = calendarDiscovery.xml.match(/<(?:\w+:)?response\b[^>]*>[\s\S]*?<\/(?:\w+:)?response>/gi) || [];
const calendars = [];

for (const block of responseBlocks) {
  const href = firstHref(block);
  if (!href) continue;

  const resourceType = firstTag(block, 'resourcetype') || '';
  const components = firstTag(block, 'supported-calendar-component-set') || '';
  const sourceBlock = firstTag(block, 'source');

  let subscriptionSource = null;
  if (sourceBlock !== null) {
    subscriptionSource = firstHref(sourceBlock) || textContent(sourceBlock) || null;
    subscriptionSource = normalizeSubscriptionUrl(subscriptionSource);
  }

  const isSubscription = Boolean(subscriptionSource);
  const isCalendarResource = /<(?:\w+:)?calendar\b/i.test(resourceType);
  const isSubscribedResource = /<(?:\w+:)?subscribed\b/i.test(resourceType);

  // Skip the calendar-home collection and DAV children such as inbox/outbox.
  if (!isSubscription && !isCalendarResource && !isSubscribedResource) continue;

  const caldavUrl = absoluteUrl(href, calendarHomeUrl);
  const displayNameBlock = firstTag(block, 'displayname');
  const displayName = displayNameBlock === null ? null : textContent(displayNameBlock);
  const parsedCaldavUrl = parseAbsoluteHttpUrl(caldavUrl);
  const pathParts = (parsedCaldavUrl?.path || String(href)).split('/').filter(Boolean);
  const calendarUri = decodeURIComponent(pathParts[pathParts.length - 1] || '');
  const readOnlyBlock = firstTag(block, 'read-only');
  const readOnlyText = readOnlyBlock === null ? '' : textContent(readOnlyBlock).toLowerCase();
  const readOnly = readOnlyBlock !== null && !['', '0', 'false', 'no'].includes(readOnlyText);

  const icsUrl = isSubscription
    ? subscriptionSource
    : `${caldavUrl}${caldavUrl.includes('?') ? '&' : '?'}export`;

  calendars.push({
    calendarUri,
    displayName: displayName || calendarUri || caldavUrl,
    kind: isSubscription ? 'subscription_ics' : 'nextcloud_caldav',
    isSubscription,
    supportsVEvent: /VEVENT/i.test(components),
    supportsVTodo: /VTODO/i.test(components),
    readOnly,
    caldavUrl,
    subscriptionSourceUrl: isSubscription ? subscriptionSource : null,
    icsUrl,
    fetchAuth: isSubscription ? 'none' : 'nextcloud_basic',
  });
}

calendars.sort((a, b) => a.displayName.localeCompare(b.displayName));

const deduped = [];
const seen = new Set();
for (const calendar of calendars) {
  const key = `${calendar.kind}|${calendar.icsUrl}`;
  if (seen.has(key)) continue;
  seen.add(key);
  deduped.push(calendar);
}

const warnings = [];
if (deduped.length === 0) {
  warnings.push('No calendar resources were discovered. Verify the Nextcloud account has calendars visible through CalDAV.');
}

return [{
  json: {
    status: warnings.length ? 'ok_with_warnings' : 'ok',
    discoveredAt: new Date().toISOString(),
    timezone: cfg.timezone,
    instanceBaseUrl,
    davRootUrl,
    principalUrl,
    principalDiscoveryMode,
    calendarHomeUrl,
    calendarHomeDiscoveryMode,
    calendarCount: deduped.length,
    subscriptionCount: deduped.filter((c) => c.isSubscription).length,
    calendars: deduped,
    cache: cfg.cache,
    redisExpected: cfg.redisExpected,
    warnings,
    metadata: {
      discoveryMethod: 'dav_principal_then_caldav_home_then_propfind_depth_1',
      n8nCompatibility: '2.7.3_code_node_propfind_workaround',
      subscriptionDetection: 'calendarserver.org/ns/source',
      normalCalendarReadMode: 'nextcloud_ics_export',
      subscriptionReadMode: 'direct_external_ics',
    },
  },
}];

const data = $input.first().json;

const cachePayload = {
  schemaVersion: data.cache.schemaVersion,
  generatedAt: data.discoveredAt,
  timezone: data.timezone,
  calendarHomeUrl: data.calendarHomeUrl,
  calendars: data.calendars,
};

return [{
  json: {
    ...data,
    cachePayload,
  },
}];

const data = $input.first().json;
const { cachePayload, ...rest } = data;

return [{
  json: {
    ...rest,
    cache: {
      ...rest.cache,
      written: true,
    },
  },
}];
